/* 全部词库 · CEFR A1 / A2 / B1 / B2 / B2–C1，共 6925 词
   （A1 460 / A2 465 / B1 2000 / B2 2000 / B2–C1 2000）
   格式：[英文, 中文, 类别, 难度, 词性]   难度：1=A1  2=A2  3=B1  4=B2  5=B2–C1
   词性只有五种：n 名词 / v 动词 / adj 形容词 / adv 副词 / num 数词（中文名在 POS_CN 里）。

   **一个难度就是一章，章与章之间的词不重复**（用户定的）：
   第一章「石廊」只出难度 1，第二章「锈庭」只出难度 2，第三章「烬渊」难度 3，第四章「墟心」难度 4。
   **只有第五章「无尽」是例外** —— 它的 wordLv 是数组 [3,4,5]，B1 / B2 / B2–C1 三档混着出，
   难度 5 这一档（2000 词）是它专属的，前四章碰不到。
   哪一章用哪个难度写在 content.js 的 `CHAPTERS[].wordLv` 上。
   加词直接往 WORDS 里加，**五个字段都要给**；类别要在 CAT_CN 里有对应中文名。
   **英文不能重复** —— WMAP 按英文做键，重了会静默覆盖。
   **同一难度里中文释义也不能重复** —— 选择题的干扰项就在同难度里挑，
   两个词共用一个中文会出现「两个选项都对」。加词后跑一遍同级释义查重。
   **每个难度的每个类别、每个词性都要 ≥6 个词** —— 普通怪按类别出题，
   Boss 弱点按词性挑（game.js 的 chapterPos()），不够 6 个就挑不到。
   **英文最长 11 个字母** —— 拼写题的字格只量到 11，再长会在 390×667 上折行。
   虚词（func：代词/介词/连词/冠词）已经整类删掉了（用户 2026-09），别加回来。
   怪物按类别出题（见 content.js 里每只怪的 cat 字段）。*/
