/* 派生索引 —— 加词后自动生效，不用手动维护 */
var WMAP = {};
WORDS.forEach(function(w){ WMAP[w[0]] = {en:w[0], cn:w[1], cat:w[2], lv:w[3] || 1, pos:w[4] || "n"}; });
var BYCAT = {};
WORDS.forEach(function(w){ (BYCAT[w[2]] = BYCAT[w[2]] || []).push(WMAP[w[0]]); });
/* 按词性分桶 —— Boss 的弱点就在这里面挑 */
var BYPOS = {};
WORDS.forEach(function(w){ (BYPOS[w[4] || "n"] = BYPOS[w[4] || "n"] || []).push(WMAP[w[0]]); });
/* 按难度分桶，出题时按章节挑桶 */
var BYLV = {1:[], 2:[], 3:[], 4:[], 5:[]};
WORDS.forEach(function(w){ BYLV[w[3] || 1].push(WMAP[w[0]]); });
var ALLW = WORDS.map(function(w){ return WMAP[w[0]]; });
